CREATE TABLE homes (id TEXT PRIMARY KEY NOT NULL, name TEXT NOT NULL CONSTRAINT homes_name_not_empty CHECK (length(trim(name)) > 0));
CREATE TABLE members (id TEXT PRIMARY KEY NOT NULL, home_id TEXT NOT NULL CONSTRAINT members_home_fk REFERENCES homes(id) ON DELETE CASCADE, name TEXT NOT NULL CONSTRAINT members_name_not_empty CHECK (length(trim(name)) > 0));
CREATE TABLE bills (id TEXT PRIMARY KEY NOT NULL, home_id TEXT NOT NULL CONSTRAINT bills_home_fk REFERENCES homes(id) ON DELETE CASCADE, title TEXT NOT NULL CONSTRAINT bills_title_not_empty CHECK (length(trim(title)) > 0), total_cents INTEGER NOT NULL CONSTRAINT bills_positive_total CHECK (total_cents > 0 AND typeof(total_cents) = 'integer'));
CREATE TABLE shares (id TEXT PRIMARY KEY NOT NULL, bill_id TEXT NOT NULL CONSTRAINT shares_bill_fk REFERENCES bills(id) ON DELETE CASCADE, member_id TEXT NOT NULL CONSTRAINT shares_member_fk REFERENCES members(id) ON DELETE CASCADE, amount_cents INTEGER NOT NULL CONSTRAINT shares_nonnegative_amount CHECK (amount_cents >= 0 AND typeof(amount_cents) = 'integer'), paid_at TEXT, payment_key TEXT, CONSTRAINT shares_one_per_member_per_bill UNIQUE (bill_id, member_id));
CREATE UNIQUE INDEX shares_payment_key_unique ON shares(payment_key) WHERE payment_key IS NOT NULL;
